cat >> tests/test_splitting.py <<'EOF'


def test_split_by_percent_follows_the_percentages():
    shares = split_by_percent(3000, [("alice", 50), ("bob", 30), ("carol", 20)])
    assert shares == {"alice": 1500, "bob": 900, "carol": 600}


def test_split_by_percent_keeps_every_cent():
    shares = split_by_percent(1001, [("alice", 50), ("bob", 50)])
    assert shares == {"alice": 501, "bob": 500}


@pytest.mark.parametrize("percents", [[("alice", 50), ("bob", 40)], [("alice", 60), ("bob", 50)]])
def test_split_by_percent_rejects_percentages_that_do_not_add_up_to_100(percents):
    with pytest.raises(MoneyError, match="add up to 100"):
        split_by_percent(1000, percents)


def test_split_by_percent_rejects_a_person_listed_twice():
    with pytest.raises(MoneyError, match="bob"):
        split_by_percent(1000, [("bob", 50), ("bob", 50)])


@pytest.mark.parametrize(("text", "expected"), [("alice=50", ("alice", 50)), (" bob = 100 ", ("bob", 100))])
def test_parse_percent(text, expected):
    assert parse_percent(text) == expected


@pytest.mark.parametrize("text", ["alice", "alice=", "=50", "alice=50.5", "alice=-5", "alice=abc", "alice=0", "alice=101"])
def test_parse_percent_rejects_bad_input(text):
    with pytest.raises(MoneyError):
        parse_percent(text)
