def test_add_records_a_percentage_split(run):
    code, out, _ = run(
        "add", "--paid-by", "alice", "--amount", "30.00", "--description", "Pizza",
        "--percent", "alice=50", "--percent", "bob=30", "--percent", "carol=20",
    )  # fmt: skip
    assert code == 0
    assert out == "added #1: 30.00 for Pizza\n"
    assert run("balances")[1] == "alice 15.00\nbob -9.00\ncarol -6.00\n"


def test_percentages_that_do_not_add_up_to_100_are_rejected(run):
    code, _, err = run(
        "add", "--paid-by", "alice", "--amount", "9", "--description", "x",
        "--percent", "alice=50", "--percent", "bob=40",
    )  # fmt: skip
    assert code == 2
    assert "100" in err
    assert run("list")[1] == ""


@pytest.mark.parametrize(
    "split",
    [[], ["--with", "bob", "--percent", "bob=100"]],
    ids=["neither", "both"],
)
def test_add_needs_exactly_one_of_with_and_percent(run, split):
    with pytest.raises(SystemExit) as exit_info:
        run("add", "--paid-by", "alice", "--amount", "9", "--description", "x", *split)
    assert exit_info.value.code == 2
